+
+pragma ComponentBehavior: Bound
+
+import QtQuick
+import QtQuick.Layouts
+import QtQuick.Templates as T
+
+import org.kde.kirigami as Kirigami
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.plasma.extras as PlasmaExtras
+import org.kde.plasma.plasmoid
+
+ColumnLayout {
+    id: root
+
+    // Enabled outputs.
+    //
+    // type: [{
+    //  id: int,
+    //  name: string,
+    //  label: string,
+    //  rotation: enum<KScreen::Output::Rotation>,
+    //  autoRotate: bool,
+    // }]
+    property var outputs
+
+    // Name of the screen the applet is on, selected by default
+    property string screenName
+
+    property int selectedOutputId: -1
+
+    readonly property var selectedOutput: {
+        const selected = outputs.find(output => output.id === selectedOutputId);
+        return selected ?? outputs.find(output => output.name === screenName) ?? outputs[0];
+    }
+
+    spacing: Kirigami.Units.smallSpacing * 2
+
+    Kirigami.Heading {
+        Layout.fillWidth: true
+        level: 3
+        text: i18n("Screen Rotation")
+    }
+
+    PlasmaComponents3.ComboBox {
+        Layout.fillWidth: true
+        visible: root.outputs.length > 1
+        model: root.outputs
+        textRole: "label"
+        currentIndex: root.outputs.findIndex(output => output.id === root.selectedOutput?.id)
+        onActivated: index => root.selectedOutputId = root.outputs[index].id
+    }
+
+    RowLayout {
+        Layout.fillWidth: true
+        spacing: Kirigami.Units.smallSpacing
+        uniformCellSizes: true
+        enabled: !(root.selectedOutput?.autoRotate ?? false)
+
+        Repeater {
+            model: [
+                // KScreen::Output::Rotation values
+                { rotation: 1, angle: 0, label: i18n("No Rotation") },
+                { rotation: 2, angle: 90, label: i18n("90° Clockwise") },
+                { rotation: 4, angle: 180, label: i18n("Upside Down") },
+                { rotation: 8, angle: 270, label: i18n("90° Counterclockwise") },
+            ]
+
+            PlasmaComponents3.ToolButton {
+                id: rotationDelegate
+
+                required property var modelData
+
+                Layout.fillWidth: true
+                checkable: true
+                checked: root.selectedOutput?.rotation === rotationDelegate.modelData.rotation
+                text: modelData.label
+                display: T.Button.IconOnly
+
+                contentItem: Kirigami.Icon {
+                    implicitWidth: Kirigami.Units.iconSizes.medium
+                    implicitHeight: Kirigami.Units.iconSizes.medium
+                    source: "tv"
+                    rotation: rotationDelegate.modelData.angle
+                }
+
+                onClicked: {
+                    // Show the new rotation only once it has been applied
+                    checked = Qt.binding(() => root.selectedOutput?.rotation === rotationDelegate.modelData.rotation);
+                    Plasmoid.setRotation(root.selectedOutput.id, rotationDelegate.modelData.rotation); // qmllint disable missing-property
+                }
+
+                Accessible.name: text
+                Accessible.role: Accessible.RadioButton
+                PlasmaComponents3.ToolTip { text: rotationDelegate.text }
+            }
+        }
+    }
+
+    PlasmaExtras.DescriptiveLabel {
+        Layout.fillWidth: true
+        wrapMode: Text.Wrap
+        text: i18n("This screen rotates automatically.")
+        font: Kirigami.Theme.smallFont
+        visible: root.selectedOutput?.autoRotate ?? false
+    }
+}
