 #include <algorithm>

 K_PLUGIN_CLASS_WITH_JSON(KScreenApplet, "metadata.json")
@@ -53,6 +55,47 @@ void KScreenApplet::applyLayoutPreset(KScreen::OsdAction::Action action)
     KScreen::OsdAction::applyAction(m_screenConfiguration, action);
 }

+QVariantList KScreenApplet::outputs() const
+{
+    return m_outputs;
+}
+
+void KScreenApplet::setRotation(int outputId, int rotation)
+{
+    if (!m_screenConfiguration) {
+        return;
+    }
+
+    const KScreen::ConfigPtr config = m_screenConfiguration->clone();
+    const KScreen::OutputPtr output = config->output(outputId);
+    if (!output || !output->isEnabled() || output->rotation() == rotation) {
+        return;
+    }
+
+    const QRect oldGeometry(output->pos(), config->logicalSizeForOutputInt(*output));
+    output->setRotation(static_cast<KScreen::Output::Rotation>(rotation));
+    const QSize newSize = config->logicalSizeForOutputInt(*output);
+    output->setExplicitLogicalSize(newSize);
+
+    // Keep the screens to the right of and below the rotated one next to it
+    const QSize delta = newSize - oldGeometry.size();
+    for (const KScreen::OutputPtr &other : config->outputs()) {
+        if (other == output || !other->isEnabled()) {
+            continue;
+        }
+        QPoint pos = other->pos();
+        if (pos.x() >= oldGeometry.x() + oldGeometry.width()) {
+            pos.rx() += delta.width();
+        }
+        if (pos.y() >= oldGeometry.y() + oldGeometry.height()) {
+            pos.ry() += delta.height();
+        }
+        other->setPos(pos);
+    }
+
+    new KScreen::SetConfigOperation(config);
+}
+
 void KScreenApplet::checkOutputs()
 {
     if (!m_screenConfiguration) {
@@ -69,6 +112,32 @@ void KScreenApplet::checkOutputs()
     if (m_connectedOutputCount != oldConnectedOutputCount) {
         emit connectedOutputCountChanged();
     }
+
+    // List the screens from left to right, as they are arranged
+    QList<KScreen::OutputPtr> sortedOutputs;
+    std::copy_if(outputs.begin(), outputs.end(), std::back_inserter(sortedOutputs), [](const KScreen::OutputPtr &output) {
+        return output->isEnabled();
+    });
+    std::ranges::sort(sortedOutputs, [](const KScreen::OutputPtr &left, const KScreen::OutputPtr &right) {
+        return std::pair(left->pos().x(), left->pos().y()) < std::pair(right->pos().x(), right->pos().y());
+    });
+
+    QVariantList enabledOutputs;
+    for (const KScreen::OutputPtr &output : std::as_const(sortedOutputs)) {
+        const bool autoRotate =
+            output->capabilities() & KScreen::Output::Capability::AutoRotation && output->autoRotatePolicy() != KScreen::Output::AutoRotatePolicy::Never;
+        enabledOutputs.append(QVariantMap{
+            {QStringLiteral("id"), output->id()},
+            {QStringLiteral("name"), output->name()},
+            {QStringLiteral("label"), Utils::outputName(output)},
+            {QStringLiteral("rotation"), static_cast<int>(output->rotation())},
+            {QStringLiteral("autoRotate"), autoRotate},
+        });
+    }
+    if (enabledOutputs != m_outputs) {
+        m_outputs = enabledOutputs;
+        emit outputsChanged();
+    }
 }

 QVariant KScreenApplet::availableActions()
